package com.drogaria.backend.service;
import com.drogaria.backend.dto.*; import com.drogaria.backend.entity.*; import com.drogaria.backend.exception.ApiException; import com.drogaria.backend.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.List;
@Service public class AgendamentoService { private final AgendamentoRepository r; private final ClienteRepository clientes; private final ServicoRepository servicos; private final LojaRepository lojas; public AgendamentoService(AgendamentoRepository r,ClienteRepository c,ServicoRepository s,LojaRepository l){this.r=r;clientes=c;servicos=s;lojas=l;} public AgendamentoResponse criar(AgendamentoRequest x){if(r.existsByLojaIdAndDataHora(x.getIdLoja(),x.getDataHora()))throw new ApiException("Horario ja reservado",HttpStatus.CONFLICT);Agendamento a=new Agendamento();a.setDataHora(x.getDataHora());a.setStatus("AGENDADO");a.setCliente(clientes.findById(x.getIdCliente()).orElseThrow(()->new ApiException("Cliente nao encontrado",HttpStatus.NOT_FOUND)));a.setServico(servicos.findById(x.getIdServico()).orElseThrow(()->new ApiException("Servico nao encontrado",HttpStatus.NOT_FOUND)));a.setLoja(lojas.findById(x.getIdLoja()).orElseThrow(()->new ApiException("Loja nao encontrada",HttpStatus.NOT_FOUND)));return new AgendamentoResponse(r.save(a));} public AgendamentoResponse buscar(Integer id){return new AgendamentoResponse(r.findById(id).orElseThrow(()->new ApiException("Agendamento nao encontrado",HttpStatus.NOT_FOUND)));} public List<AgendamentoResponse> cliente(Integer id){return r.findByClienteId(id).stream().map(AgendamentoResponse::new).toList();} public List<AgendamentoResponse> loja(Integer id){return r.findByLojaId(id).stream().map(AgendamentoResponse::new).toList();} public void cancelar(Integer id){Agendamento a=r.findById(id).orElseThrow(()->new ApiException("Agendamento nao encontrado",HttpStatus.NOT_FOUND));a.setStatus("CANCELADO");r.save(a);} }